public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    boolean lastCharWasEscapeChar = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && !lastCharWasEscapeChar) {
            lastCharWasEscapeChar = true;
            continue;
        }

        if (lastCharWasEscapeChar) {
            lastCharWasEscapeChar = false;

            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'u':
                    String hexChars = str.substring(i, i+4);
                    if (hexChars.length < 4) {
                        throw new IllegalArgumentException("Invalid escape sequence");
                    }
                    char unicode = (char) Integer.parseInt(hexChars, 16);
                    sb.append(unicode);
                    i += 4; // Move the index to the end of the escape sequence
                    break;
                case '\\':
                case '/':
                case '"':
                    sb.append(c);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence");
            }
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

