void pop(String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.startsWith("L")) {
        // If it is a type descriptor, check if it has a generic type
        if (descriptor.contains("<")) {
            // If it has a generic type, check the number of arguments
            if (descriptor.split("<").length == 2) {
                // If it has one argument, pop a string value from the output frame stack
                outputFrameStack.pop();
            } else {
                // If it has multiple arguments, pop a list of values from the output frame stack
                outputFrameStack.popList();
            }
        } else {
            // If it does not have a generic type, pop a string value from the output frame stack
            outputFrameStack.pop();
        }
    } else {
        // If the descriptor is a method descriptor, check if it has an argument list
        if (descriptor.contains("(")) {
            // If it has an argument list, pop the arguments from the output frame stack
            String[] args = descriptor.substring(descriptor.indexOf("(") + 1, descriptor.indexOf(")")).split(",");
            for (String arg : args) {
                outputFrameStack.pop(arg);
            }
        } else {
            // If it does not have an argument list, do nothing
        }
    }
}

